{
  "type": "commercial_photography",
  "subject": {
    "age": 25,
    "ethnicity": "American Caucasian woman",
    "appearance": {
      "body_proportion": "perfectly proportioned",
      "posture": "standing naturally",
      "expression": "natural, looking towards camera",
      "facial_features": "clear and refined facial features",
      "skin_detail": "finely detailed natural skin texture with realistic pores",
      "hair": "soft blonde hair",
      "makeup": "no artificial heavy makeup"
    },
    "attire": {
      "jacket": "well-fitted beige tailored blazer",
      "shirt": "crisp white shirt",
      "pants": "slim trousers",
      "shoes": "elegant leather loafers",
      "style": "chic everyday smart-casual wear"
    },
    "action": "trying on a pair of stylish modern eyeglasses, one hand elegantly adjusting the frames on her face"
  },
  "setting": {
    "location": "brightly lit, high-end optical boutique with minimalist store background",
    "position": "full body, standing naturally"
  },
  "lighting": {
    "type": "mixed light source",
    "details": "soft daylight from a large window + studio softbox key light",
    "effect": "balanced, flattering illumination, reveals true natural colors of materials, no exaggerated filters, no harsh shadows"
  },
  "camera": {
    "model": "Sony A7R IV",
    "lens": "50mm f/1.8",
    "aperture_effect": "shallow depth of field, ultra-sharp focus on the face, glasses and outfit"
  },
  "output": {
    "format": "8k RAW photo",
    "style": "photorealistic, hyperrealistic, highly detailed",
    "color": "natural color, no over-saturated colors"
  },
  "avoid": [
    "distorted limbs",
    "unnatural body proportions",
    "artificial heavy makeup",
    "harsh shadows",
    "over-saturated colors"
  ]
}

